<script lang="ts">
 import {onMount} from 'svelte';import {invoke} from '@tauri-apps/api/core';import {listen} from '@tauri-apps/api/event';
 import ProviderLogo from './ProviderLogo.svelte';import UiIcon from './UiIcon.svelte';
 import type{OverlaySnapshot}from './launcher_extensions';import type{ContentOperation}from './content_operations';
 let{kind,frame=null,preview=false}:{kind:'resourcepack'|'shader';frame?:OverlaySnapshot|null;preview?:boolean}=$props();
 type Pack={name:string;enabled:boolean;order:number};type Content={game_version:string;loader:string;shader_loader:string|null;resourcepacks:Pack[];shaderpacks:Pack[]};
 type Project={id:string;provider:string;title:string;description:string;icon_url:string;preview_url:string;author:string};
 type Version={id:string;name:string;game_versions:string[];release_type:string};
 let content=$state<Content|null>(null),projects=$state<Project[]>([]),categories=$state<{id:string;name:string;provider:string}[]>([]);
 let provider=$state('both'),category=$state(''),query=$state(''),page=$state(1),pages=$state(1),busy=$state(false),working=$state(false),message=$state(''),error=$state(''),progress=$state<ContentOperation|null>(null);
 let selected=$state<Project|null>(null),versions=$state<Version[]>([]),file=$state(''),tab=$state('explore');let request=0;
 let packs=$derived(kind==='shader'?content?.shaderpacks??[]:content?.resourcepacks??[]);
 async function refresh(){if(frame?.pid)content=await invoke<Content>('hud_game_content',{pid:frame.pid});}
 async function search(reset=false){if(reset)page=1;if(preview||!content)return;const id=++request;busy=true;error='';try{const data=await invoke<{projects:Project[];total_pages:number}>('studio_search',{provider,query,projectType:kind,gameVersion:content.game_version,loader:'all',sort:'relevance',page,category:category||null});if(id===request){projects=data.projects;pages=data.total_pages;}}catch(e){if(id===request)error=String(e);}finally{if(id===request)busy=false;}}
 $effect(()=>{const source=provider,type=kind;let alive=true;void invoke<typeof categories>('studio_categories',{provider:source,projectType:type}).then(rows=>{if(alive)categories=rows;}).catch(()=>{});return()=>{alive=false;};});
 onMount(()=>{let alive=true,stop:(()=>void)|undefined;void listen<ContentOperation>('studio-progress',event=>{if(alive&&working)progress=event.payload;}).then(unlisten=>{if(alive)stop=unlisten;else unlisten();});if(!preview)void refresh().then(()=>search()).catch(e=>error=String(e));return()=>{alive=false;request++;stop?.();};});
 async function choose(project:Project){selected=project;versions=[];file='';working=true;error='';try{const detail=await invoke<{versions:Version[]}>('studio_project',{provider:project.provider,projectId:project.id});if(selected?.id===project.id&&selected.provider===project.provider){versions=detail.versions.filter(v=>v.game_versions.includes(content!.game_version));file=versions.find(v=>v.release_type==='release')?.id??versions[0]?.id??'';}}catch(e){error=String(e);}finally{working=false;}}
 async function install(){if(!selected||!file||!frame?.pid)return;working=true;error='';progress=null;try{message=await invoke<string>('hud_install_content',{pid:frame.pid,provider:selected.provider,projectId:selected.id,fileId:file,projectType:kind});await refresh();selected=null;tab='installed';message+=' · Ya puedes activarlo en esta pestaña.';}catch(e){error=String(e);}finally{working=false;}}
 async function activate(name:string,enabled:boolean){if(!frame?.pid)return;working=true;error='';message='Esperando confirmación del juego…';try{let values:Record<string,string>;if(kind==='shader')values={name:enabled?name:''};else{const selected=packs.filter(p=>p.name===name?enabled:p.enabled).map(p=>'file/'+p.name);values=Object.fromEntries(['vanilla',...selected].map((v,i)=>['pack.'+i,v]));}message=await invoke<string>('hud_game_command',{pid:frame.pid,action:kind==='shader'?'shader':'packs',values});await refresh();}catch(e){error=String(e);message='';}finally{working=false;}}
</script>
<section class="browser"><header><h3>{kind==='shader'?'Shaders':'ResourcePacks'}</h3><small>Minecraft {content?.game_version??'· abre una partida'} · Carpeta de esta instalación</small></header>
 {#if preview}<p>El catálogo se conecta a la versión y carpeta de la partida al abrir F8 dentro de Minecraft.</p>{/if}
 {#if kind==='shader'&&!content?.shader_loader}<p class="warning" role="status">No se detectó Iris, OptiFine u Oculus. Puedes descargar shaders, pero para activarlos necesitas instalar un cargador de shaders compatible y reiniciar Minecraft.</p>{:else if kind==='shader'}<p>Cargador detectado: {content?.shader_loader}. La activación espera confirmación del juego.</p>{/if}
 <nav><button class:active={tab==='explore'} onclick={()=>tab='explore'}>Explorar y descargar</button><button class:active={tab==='installed'} onclick={()=>{tab='installed';void refresh().catch(e=>error=String(e));}}>Instalados · {packs.length}</button></nav>
 {#if error}<p role="alert" class="error">{error}</p>{/if}{#if message}<p role="status">{message}</p>{/if}
 {#if working&&progress}<div class="progress" role="status"><span>{progress.stage} · {Math.round(progress.percent)}%</span><progress max="100" value={progress.percent}></progress><small>{progress.detail}</small></div>{/if}
 {#if selected}<section class="selection"><strong>{selected.title}</strong><select aria-label="Archivo compatible" bind:value={file}>{#each versions as v}<option value={v.id}>{v.name} · {v.release_type}</option>{/each}</select>{#if !working&&!versions.length}<p>El autor no publicó un archivo compatible con esta versión.</p>{/if}<div class="actions"><button disabled={working||!file} onclick={()=>void install()}><UiIcon name="download" size={14}/>Descargar en esta partida</button><button disabled={working} onclick={()=>selected=null}>Cerrar</button></div></section>{/if}
 {#if tab==='explore'}<form onsubmit={e=>{e.preventDefault();void search(true);}}><input aria-label="Buscar packs o shaders" bind:value={query} placeholder={kind==='shader'?'Buscar iluminación y shaders…':'Buscar texturas y sonidos…'}/><button disabled={busy||preview}>Buscar</button></form><div class="filters"><label>Plataforma<select bind:value={provider} onchange={()=>{category='';void search(true);}}><option value="both">Modrinth y CurseForge</option><option value="modrinth">Modrinth</option><option value="curseforge">CurseForge</option></select></label><label>Categoría<select bind:value={category} onchange={()=>void search(true)}><option value="">Todas</option>{#each categories as c}<option value={c.id}>{c.name} · {c.provider}</option>{/each}</select></label></div>
 <div class="grid" aria-busy={busy}>{#each projects as p}<article><div class="cover">{#if p.preview_url||p.icon_url}<img src={p.preview_url||p.icon_url} alt="" loading="lazy"/>{:else}<UiIcon name="image" size={32}/>{/if}</div><div class="body"><ProviderLogo provider={p.provider} size={20}/><strong>{p.title}</strong><small>por {p.author}</small><p>{p.description}</p><button disabled={working} onclick={()=>void choose(p)}>Ver archivos compatibles</button></div></article>{/each}</div>{#if !busy&&!projects.length&&!preview}<p>No hay resultados para esta versión y estos filtros.</p>{/if}<nav class="pages"><button disabled={busy||page<=1} onclick={()=>{page--;void search();}}>Anterior</button><span>{page} / {Math.max(1,pages)}</span><button disabled={busy||page>=pages} onclick={()=>{page++;void search();}}>Siguiente</button></nav>
 {:else}<div class="installed">{#each packs as p}<article><span><strong>{p.name}</strong><small>{p.enabled?'Activo':'Desactivado'}</small></span><button disabled={working||(kind==='shader'&&!content?.shader_loader)} onclick={()=>void activate(p.name,!p.enabled)}>{p.enabled?'Desactivar':'Activar'}</button></article>{/each}{#if !packs.length}<p>Aún no hay archivos en esta carpeta.</p>{/if}</div>{/if}
</section>
<style>
.browser{display:grid;gap:14px;font-size:12px}.browser h3{margin:0;font-size:18px}.browser header{display:grid;gap:6px}.browser small,.browser p{color:#b8a9c4;font-size:11px;line-height:1.6;margin:0}.browser button,.browser select,.browser input{font:inherit;color:inherit;background:#15101e;border:1px solid #ffffff25;border-radius:4px;padding:10px;min-width:0;color-scheme:dark}.browser button{cursor:pointer}.browser button:hover,.browser button.active{border-color:#a855f7;background:#a855f723}.browser button:disabled{opacity:.4;cursor:default}.browser nav,.actions{display:flex;gap:8px;align-items:center}.browser form{display:grid;grid-template-columns:1fr auto;gap:8px}.filters{display:grid;grid-template-columns:1fr 1fr;gap:10px}.filters label{display:grid;gap:6px}.grid{display:grid;grid-template-columns:repeat(2,minmax(100px,1fr));gap:12px}.grid article,.selection{border:1px solid #ffffff22;border-radius:6px;overflow:hidden;background:#0c091280}.cover{height:110px;background:#161020;display:grid;place-items:center}.cover img{width:100%;height:100%;object-fit:cover}.body{display:grid;gap:8px;padding:12px;min-width:0}.body p{display:-webkit-box;-webkit-line-clamp:3;line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.body strong{overflow-wrap:anywhere}.selection{padding:13px;display:grid;gap:10px}.installed{display:grid;gap:8px}.installed article{display:flex;gap:12px;align-items:center;border:1px solid #ffffff20;padding:12px}.installed article>span{display:grid;gap:7px;flex:1;overflow-wrap:anywhere;min-width:0}.warning{padding:12px;border:1px solid #d4ad5c66;background:#a7791120;color:#e5cb98!important}.error{padding:10px;border:1px solid #e8797960;color:#f0b5b5!important}.pages{justify-content:center}.progress{display:grid;gap:6px}.progress progress{width:100%;accent-color:#a855f7}
</style>
